-- ---------------------------------------------------------------------------
-- top_ball_beam : board wrapper for the Posedge-One (Spartan-6 XC6SLX9-2TQG144)
--
-- All control logic is in BallBeamCore, generated by HDL Coder from
-- simulink/bb_core.slx (see simulink/gen_hdl.m). This file only:
--   * converts the active-LOW user push-button (RESET_N, p133) into a
--     synchronous active-high reset, plus a power-on reset
--   * maps core ports to board pins (names match constraints/top_ball_beam.ucf)
-- ---------------------------------------------------------------------------
library ieee;
use ieee.std_logic_1164.all;

entity top_ball_beam is
  port (
    CLOCK       : in  std_logic;                      -- 24 MHz, p50
    RESET_N     : in  std_logic;                      -- USER_PB, active low
    HCSR04_ECHO : in  std_logic;                      -- 5 V signal: needs a divider!
    HCSR04_TRIG : out std_logic;
    SERVO       : out std_logic;
    UART_RX     : in  std_logic;                      -- from FT2232H TXD
    UART_TX     : out std_logic;                      -- to   FT2232H RXD
    LEDS        : out std_logic_vector(3 downto 0);   -- wing LEDs (optional)
    USER_LED    : out std_logic                       -- on-board LED, heartbeat
  );
end entity;

architecture rtl of top_ball_beam is
  signal rst_sync : std_logic_vector(2 downto 0) := (others => '1');
  signal por_cnt  : natural range 0 to 255 := 0;
  signal reset    : std_logic := '1';
  signal led      : std_logic_vector(3 downto 0);
begin

  -- reset: 2-flop synchroniser on the button + 256-cycle power-on reset
  process (CLOCK)
  begin
    if rising_edge(CLOCK) then
      rst_sync <= rst_sync(1 downto 0) & (not RESET_N);
      if por_cnt /= 255 then
        por_cnt <= por_cnt + 1;
        reset   <= '1';
      else
        reset   <= rst_sync(2);
      end if;
    end if;
  end process;

  u_core : entity work.BallBeamCore
    port map (
      clk       => CLOCK,
      reset     => reset,
      echo_in   => HCSR04_ECHO,
      uart_rxd  => UART_RX,
      trig_out  => HCSR04_TRIG,
      servo_out => SERVO,
      uart_txd  => UART_TX,
      led0      => led(0),
      led1      => led(1),
      led2      => led(2),
      led3      => led(3)
    );

  LEDS     <= led;
  USER_LED <= led(3);

end architecture;
